/* allofus.one · ADS YOU CONTROL + RUN AN AD + MARKETING DASH (v27, Oct 23 2026)
   Four things live here:
   1. Member ad preferences: 'off' | 'local' (default: only Brand pages near you or that you follow) | 'all', plus hidden
      categories. Stored on profiles.ad_pref / profiles.ad_filters when signed in (v27-ads.sql), mirrored to localStorage
      so the setting works on this device even before the SQL is run. aou-boost.js reads these when it picks a feed ad.
   2. "Run an ad": a 3-step composer (what, who, how long) ending in a checkout that writes an ad_orders row
      (status 'awaiting_payment'). Payment today is manual (invoice); the Authorize.net Accept Hosted button opens
      when CONFIG.AUTHNET_PAY_URL is set. We never collect card numbers on our pages.
   3. Marketing dash (/?v=marketing): Brand page views, followers, reach, ads, spend, clicks and a Grow checklist.
   4. Admin "Ads & orders" section + the Business metrics tile row for the admin dashboard.
   Charts are inline SVG, single hue, thin marks, hover titles; no chart library. */
import { CONFIG } from './aou-config.js';
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const $ = (s, r = document) => r.querySelector(s), $$ = (s, r = document) => [...r.querySelectorAll(s)];
const PHONE = '1-800-481-8638';
const money = (c) => '$' + (Math.round(c || 0) / 100).toLocaleString('en-US', { minimumFractionDigits: (c || 0) % 100 ? 2 : 0, maximumFractionDigits: 2 });
const fmt = (n) => (n == null ? '—' : Number(n).toLocaleString());
const ago = (t) => { if (!t) return '—'; const s = (Date.now() - new Date(t).getTime()) / 1000; if (s < 60) return 'just now'; if (s < 3600) return Math.floor(s / 60) + 'm ago'; if (s < 86400) return Math.floor(s / 3600) + 'h ago'; return Math.floor(s / 86400) + 'd ago'; };
const lsGet = (k, d) => { try { const v = localStorage.getItem(k); return v == null ? d : v; } catch (e) { return d; } };
const lsSet = (k, v) => { try { localStorage.setItem(k, v); } catch (e) { } };
const miniToast = (m) => { const t = document.createElement('div'); t.textContent = m; t.setAttribute('role', 'status'); t.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:#14183a;color:#fff;padding:9px 16px;border-radius:12px;font:700 13px Poppins,Arial;z-index:1300;box-shadow:0 8px 24px rgba(0,0,0,.3);max-width:92vw'; document.body.appendChild(t); setTimeout(() => t.remove(), 2800); };

/* ---------- the price ladder (fixed; the server stores what the client sent, the admin confirms payment) ---------- */
export const PLANS = [
  { k: 'week', name: '1 week', days: 7, cents: 1900, note: 'Try it on one offer' },
  { k: 'month', name: '30 days', days: 30, cents: 4900, note: 'Most Brand pages pick this', best: true },
  { k: 'quarter', name: '90 days', days: 90, cents: 14900, note: 'A full season, 1/3 off' },
];
export const VERIFIED_ADDON_CENTS = 900;  // Verified badge on the Brand page for the length of the ad (min 30 days)
export const CATEGORIES = [['general', 'General / other'], ['home', 'Home services'], ['food', 'Food & drink'], ['health', 'Health & wellness'], ['retail', 'Shops & products'], ['auto', 'Auto'], ['events', 'Events & entertainment'], ['realestate', 'Real estate'], ['professional', 'Professional services'], ['finance', 'Finance & insurance'], ['cosmetic', 'Cosmetic procedures'], ['alcohol', 'Alcohol'], ['gambling', 'Gambling'], ['politics', 'Politics & causes'], ['dating', 'Dating'], ['weight-loss', 'Weight loss']];
export const SENSITIVE = ['alcohol', 'gambling', 'politics', 'cosmetic', 'finance', 'dating', 'weight-loss'];
const catName = (k) => (CATEGORIES.find(c => c[0] === k) || [k, k])[1];

/* ---------- 1. member ad preferences ---------- */
const DEF = { pref: 'local', filters: [], g: true, videoOnly: false };
export function getAdPrefs() {
  let p = {}; try { p = JSON.parse(lsGet('aou_adprefs2', '{}')); } catch (e) { }
  let legacy = {}; try { legacy = JSON.parse(lsGet('aou_adprefs', '{}')); } catch (e) { }
  const out = Object.assign({}, DEF, p);
  if (!p.pref && legacy.on === false) out.pref = 'off';      // the old "Show ads" switch, respected
  if (p.g == null && legacy.g != null) out.g = !!legacy.g; if (p.videoOnly == null && legacy.videoOnly != null) out.videoOnly = !!legacy.videoOnly;
  if (!['off', 'local', 'all'].includes(out.pref)) out.pref = 'local';
  out.filters = Array.isArray(out.filters) ? out.filters.filter(f => typeof f === 'string').slice(0, 20) : [];
  return out;
}
export async function setAdPrefs(p, sb, me) {
  const cur = Object.assign(getAdPrefs(), p); lsSet('aou_adprefs2', JSON.stringify(cur));
  lsSet('aou_adprefs', JSON.stringify({ on: cur.pref !== 'off', g: cur.g, videoOnly: cur.videoOnly }));   // keep aou-boost.js in step
  if (sb && me) { try { const { error } = await sb.from('profiles').update({ ad_pref: cur.pref, ad_filters: cur.filters }).eq('id', me.id); if (error && !/column|schema cache/i.test(error.message)) console.warn('ad prefs', error.message); } catch (e) { } }
  return cur;
}
/* once per session: the server copy wins (so the setting follows the member across devices) */
export async function syncAdPrefs(sb, me) {
  if (!sb || !me || sessionStorage.getItem('aou_adprefs_synced') === me.id) return getAdPrefs();
  try { const { data, error } = await sb.from('profiles').select('ad_pref, ad_filters').eq('id', me.id).maybeSingle(); if (!error && data && data.ad_pref) { const cur = getAdPrefs(); cur.pref = data.ad_pref; cur.filters = data.ad_filters || []; lsSet('aou_adprefs2', JSON.stringify(cur)); lsSet('aou_adprefs', JSON.stringify({ on: cur.pref !== 'off', g: cur.g, videoOnly: cur.videoOnly })); } } catch (e) { }
  try { sessionStorage.setItem('aou_adprefs_synced', me.id); } catch (e) { }
  return getAdPrefs();
}
export function adSettingsHTML(p = getAdPrefs()) {
  const opt = (k, n, d) => `<label class="adp-opt ${p.pref === k ? 'on' : ''}"><input type="radio" name="adpref" value="${k}" ${p.pref === k ? 'checked' : ''}><b>${n}</b><small>${d}</small></label>`;
  return `<div class="adp" data-adprefs><div class="adp-row">${opt('off', 'No ads', 'Nothing sponsored, ever. Your feed is only people and pages you chose.')}${opt('local', 'Local only', 'Only Brand pages near you, in groups you are reading, or that you follow. Our default.')}${opt('all', 'All ads', 'Any paid Brand page, about one card in twelve posts. Still labeled, still rated G.')}</div>
  <details class="adp-cats" ${p.filters.length ? 'open' : ''}><summary>Hide categories ${p.filters.length ? `· <b>${p.filters.length} hidden</b>` : ''}</summary><div class="fl-chips">${CATEGORIES.filter(c => c[0] !== 'general').map(([k, n]) => `<label class="fl-btn sm ${p.filters.includes(k) ? 'p' : ''}"><input type="checkbox" data-adfilter="${k}" ${p.filters.includes(k) ? 'checked' : ''} style="width:auto"> ${SENSITIVE.includes(k) ? '' : ''}${esc(n)}</label>`).join('')}</div><p class="muted" style="font-size:12px;margin:6px 0 0">Hidden categories never reach your feed, even when you pick All ads. The server applies this, not just this device.</p></details>
  <div class="fl-chips" style="margin-top:6px"><label class="fl-btn sm"><input type="checkbox" data-adg ${p.g ? 'checked' : ''} style="width:auto"> Rated G only</label><label class="fl-btn sm"><input type="checkbox" data-adv ${p.videoOnly ? 'checked' : ''} style="width:auto"> Video ads only</label></div>
  <p class="muted" style="font-size:12px;margin:6px 0 0">Every ad says Sponsored and has Why this ad?, Hide ads like this and Turn ads off. Nothing is targeted by tracking: only by the city on your profile, the group you are reading, and pages you follow.</p></div>`;
}
export function bindAdSettings(root, { sb, me, toast } = {}) {
  const box = $('[data-adprefs]', root); if (!box) return;
  const say = toast || (() => { });
  const save = async (patch) => { const cur = await setAdPrefs(patch, sb, me); $$('.adp-opt', box).forEach(l => l.classList.toggle('on', $('input', l).value === cur.pref)); say(cur.pref === 'off' ? 'Ads are off for you.' : cur.pref === 'local' ? 'Local ads only.' : 'All ads on, with your hidden categories removed.'); };
  $$('input[name=adpref]', box).forEach(r => r.onchange = () => save({ pref: r.value }));
  $$('[data-adfilter]', box).forEach(c => c.onchange = async () => { const cur = getAdPrefs(); const set = new Set(cur.filters); if (c.checked) set.add(c.dataset.adfilter); else set.delete(c.dataset.adfilter); c.closest('label').classList.toggle('p', c.checked); await setAdPrefs({ filters: [...set] }, sb, me); say(c.checked ? catName(c.dataset.adfilter) + ' ads hidden.' : catName(c.dataset.adfilter) + ' ads allowed again.'); });
  const g = $('[data-adg]', box), v = $('[data-adv]', box); if (g) g.onchange = () => save({ g: g.checked }); if (v) v.onchange = () => save({ videoOnly: v.checked });
}
/* the footer every ad card carries */
export function adFooterHTML(ad) {
  return `<div class="adx-why"><span class="adx-tag">Sponsored</span><button type="button" data-adwhy>Why this ad?</button><button type="button" data-adhide="${esc(ad.category || 'general')}">Hide ads like this</button><button type="button" data-adoff>Turn ads off</button></div>`;
}
export function bindAdFooter(el, ad, { sb, me, toast, onChange } = {}) {
  const say = toast || miniToast;
  const why = $('[data-adwhy]', el); if (why) why.onclick = () => { const p = getAdPrefs(); const because = ad.audience === 'city' && ad.city ? `the city on your profile matches ${ad.city}` : ad.audience === 'groups' ? 'you are reading a group this Brand page chose' : p.pref === 'all' ? 'you chose All ads in your Control panel' : 'you follow this Brand page or it is near you'; sheet('Why this ad?', `<p>You see this because ${esc(because)}.</p><p>${esc(ad.brand || 'This business')} paid allofus.one to show it${ad.ends_at ? ' until ' + new Date(ad.ends_at).toLocaleDateString() : ''}. No tracking, no behavioral profile: allofus.one matches ads only on the city you typed, the group you are reading and the pages you follow.</p><p class="muted">Category: ${esc(catName(ad.category || 'general'))}. Rated ${esc(ad.rating || 'G')}.</p><div class="fl-chips"><a class="fl-btn" href="/?v=panel#p-ads">Ad settings</a><a class="fl-btn" href="/mission/#promise">Our promise</a></div>`); };
  const hide = $('[data-adhide]', el); if (hide) hide.onclick = async () => { const k = hide.dataset.adhide || 'general'; const cur = getAdPrefs(); const set = new Set(cur.filters); set.add(k); await setAdPrefs({ filters: [...set] }, sb, me); say(k === 'general' ? 'Fewer ads like this. Set your preference in Control panel → Ads.' : catName(k) + ' ads hidden from your feed.'); el.remove(); if (onChange) onChange(); };
  const off = $('[data-adoff]', el); if (off) off.onclick = async () => { await setAdPrefs({ pref: 'off' }, sb, me); say('Ads are off. Change it any time in Control panel → Ads.'); el.remove(); if (onChange) onChange(); };
}

